import { Suspense, ViewTransition } from 'react'
import { ProductGrid } from './ProductGrid'
import { ProductGridSkeleton } from './ProductSkeleton'

const pageTransitionEnterExit = {
  enter: {
    'nav-forward': 'nav-forward',
    'nav-back': 'nav-back',
    default: 'none',
  } as const,
  exit: {
    'nav-forward': 'nav-forward',
    'nav-back': 'nav-back',
    default: 'none',
  } as const,
}

export default function Home() {
  return (
    <main>
      <header className="site-header">
        <h1>Products</h1>
      </header>
      <ViewTransition
        enter={pageTransitionEnterExit.enter}
        exit={pageTransitionEnterExit.exit}
        default="none"
      >
        <Suspense
          fallback={
            <ViewTransition exit="slide-down">
              <ProductGridSkeleton />
            </ViewTransition>
          }
        >
          <ViewTransition enter="slide-up" default="none">
            <ProductGrid />
          </ViewTransition>
        </Suspense>
      </ViewTransition>
    </main>
  )
}

